mapper.delete:
DELETE FROM SCHEDULE
WHERE REPEAT_RULE_CODE IN (
	SELECT REPEAT_RULE_CODE
	FROM CLASS_REPEAT_RULE
	WHERE CLASS_CODE = #{classCode}
)

mapper.insert:

	SELECT (SELECT NVL(MAX(REPEAT_RULE_CODE), 0) FROM CLASS_REPEAT_RULE)
		+ SEQ_CLASS_REPEAT_RULE_CODE.NEXTVAL
	FROM DUAL

INSERT INTO CLASS_REPEAT_RULE (
	REPEAT_RULE_CODE, CLASS_CODE, OPERATION_START_DATE, OPERATION_END_DATE
) VALUES (
	#{repeatScheduleCode}, #{classCode}, #{repeatStartDate}, #{repeatEndDate}
)
